{"path":"fees.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Fees • {{BUSINESS_NAME}}</title>
  <meta name="description" content="Transparent session and package options for short work and ongoing support." />
  <style>
    :root{
      --bg:#0f1720; --card:#0b1220; --muted:#9aa4b2; --accent:#7dd3fc; --glass:rgba(255,255,255,0.04);
      --accent-2:#a78bfa;
      font-family: Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;
    }
    html,body{height:100%;margin:0;background:linear-gradient(180deg,var(--bg),#07101a);color:#e6eef6}
    a{color:var(--accent);text-decoration:none}
    header{display:flex;align-items:center;justify-content:space-between;padding:24px 32px}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:46px;height:46px;border-radius:10px;background:linear-gradient(135deg,var(--accent),var(--accent-2));display:flex;align-items:center;justify-content:center;font-weight:700}
    nav a{margin-left:18px;color:var(--muted);font-size:15px}
    .hero{padding:48px 32px 28px;background-image:url('assets/img/pattern.svg');background-size:360px;background-repeat:repeat;}
    .hero-inner{max-width:1100px;margin:0 auto;display:grid;grid-template-columns:1fr 380px;gap:28px;align-items:start}
    .lead{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:28px;border-radius:14px}
    h1{margin:0 0 8px;font-size:28px}
    p.lead-sub{margin:0;color:var(--muted)}
    .aside{padding:20px;border-radius:12px;background:var(--glass);border:1px solid rgba(255,255,255,0.03)}
    .comparator{display:flex;align-items:center;gap:16px;margin-top:18px}
    .toggle{background:#07121a;padding:6px;border-radius:999px;border:1px solid rgba(255,255,255,0.03);display:inline-flex}
    .toggle button{background:transparent;border:0;color:var(--muted);padding:10px 14px;border-radius:999px;cursor:pointer}
    .toggle button.active{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#052026;box-shadow:0 6px 18px rgba(125,211,252,0.12);}
    .plans{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:22px}
    .plan{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:18px;border-radius:12px;border:1px solid rgba(255,255,255,0.03)}
    .plan h3{margin:0 0 6px;font-size:16px}
    .price{font-weight:700;font-size:22px;color:var(--accent);}
    .meta{color:var(--muted);font-size:13px;margin-top:8px}
    .cta{display:inline-block;margin-top:12px;padding:10px 14px;border-radius:10px;background:var(--accent);color:#052026;font-weight:600}
    footer{max-width:1100px;margin:34px auto;color:var(--muted);font-size:13px;padding:0 32px}
    .note{background:rgba(255,255,255,0.02);padding:12px;border-radius:10px;border:1px solid rgba(255,255,255,0.03)}
    @media (max-width:900px){.hero-inner{grid-template-columns:1fr;}.plans{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">T</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">About</a>
      <a href="specialties.html">Specialties</a>
      <a href="approach.html">How I Work</a>
      <a href="fees.html">Fees</a>
      <a href="faq.html">FAQ</a>
      <a href="book.html">Schedule</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <section class="hero">
    <div class="hero-inner">
      <div class="lead">
        <h1>Choices that match how much you want to move right now</h1>
        <p class="lead-sub">I offer short, focused options and a monthly partnership. Use the switch to see an instant comparison of monthly rates and single‑package pricing.</p>

        <div class="comparator">
          <div>Show prices as</div>
          <div class="toggle" role="tablist" aria-label="Pricing mode">
            <button id="mode-monthly" class="active" data-mode="monthly">Monthly</button>
            <button id="mode-package" data-mode="package">Package</button>
          </div>
        </div>

        <div class="plans" id="plans">
          <div class="plan" data-monthly="220" data-package="600">
            <h3>Momentum Subscription</h3>
            <div class="price" data-display>—</div>
            <div class="meta">Ongoing weekly sessions; steady support and planning.</div>
            <a class="cta" href="{{PRIMARY_CTA_URL}}" id="cta-momentum">{{PRIMARY_CTA_LABEL}}</a>
          </div>

          <div class="plan" data-monthly="120" data-package="320">
            <h3>Focused Intensive — 3 sessions</h3>
            <div class="price" data-display>—</div>
            <div class="meta">Three close, task-oriented sessions to address a specific challenge.</div>
            <a class="cta" href="{{PRIMARY_CTA_URL}}" id="cta-intensive">Book the Intensive</a>
          </div>

          <div class="plan" data-monthly="95" data-package="540">
            <h3>Bridge Support — 6 sessions</h3>
            <div class="price" data-display>—</div>
            <div class="meta">Short-term series for transitions and clearer next steps.</div>
            <a class="cta" href="{{PRIMARY_CTA_URL}}" id="cta-bridge">Arrange a Conversation</a>
          </div>
        </div>

      </div>

      <aside class="aside">
        <h4 style="margin:0 0 8px">Notes on how I frame fees</h4>
        <div style="color:var(--muted);font-size:14px">"Monthly" shows an estimated recurring investment if you meet regularly. "Package" shows a one‑time cost for a bundled set of sessions at a small savings. No medical claims — just options you can pick from and discuss further.</div>

        <div style="margin-top:14px">
          <strong style="display:block;margin-bottom:6px">Need a custom plan?</strong>
          <div style="color:var(--muted);font-size:14px">I also create tailored bundles when timing or frequency matters. Reach out and we can outline a brief plan.</div>
        </div>
      </aside>

    </div>
  </section>

  <main style="max-width:1100px;margin:22px auto;padding:0 32px">
    <div class="note">
      <strong>Confidentiality & scope</strong>
      <div style="color:var(--muted);margin-top:6px">Sessions are confidential within professional and legal limits. I do not offer emergency crisis services. If you are in crisis or danger, please contact local emergency services or a 24/7 crisis line immediately.</div>
    </div>

    <section style="margin-top:18px">
      <h3 style="margin-bottom:8px">Payments & insurance</h3>
      <p style="color:var(--muted)">I accept private pay. Receipts for out-of-network reimbursement can be provided upon request. We can discuss sliding scale options in a first conversation when appropriate.</p>
    </section>
  </main>

  <footer>
    <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px">
      <div style="color:var(--muted)">Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or <a href="mailto:{{EMAIL}}">email</a>.</div>
      <div style="color:var(--muted)">Serving <span>{{CITY}}, {{STATE}}</span></div>
    </div>
  </footer>

  <script>
    // Pricing comparator with animated numbers
    (function(){
      const btnMonthly = document.getElementById('mode-monthly');
      const btnPackage = document.getElementById('mode-package');
      const plans = document.querySelectorAll('.plan');
      let mode = 'monthly';
      function animateValue(el, start, end, duration){
        let startTime = null;
        const step = (timestamp)=>{
          if(!startTime) startTime = timestamp;
          const progress = Math.min((timestamp-startTime)/duration,1);
          const value = Math.round(start + (end-start)*progress);
          el.textContent = '$' + value;
          if(progress<1) requestAnimationFrame(step);
        };
        requestAnimationFrame(step);
      }
      function setMode(newMode){
        mode = newMode;
        btnMonthly.classList.toggle('active', mode==='monthly');
        btnPackage.classList.toggle('active', mode==='package');
        plans.forEach(p=>{
          const display = p.querySelector('[data-display]');
          const target = Number(p.dataset[mode]);
          const currentText = display.textContent.replace(/[^0-9]/g,'');
          const current = currentText ? Number(currentText) : 0;
          animateValue(display,current,target,600);
        });
      }
      btnMonthly.addEventListener('click',()=>setMode('monthly'));
      btnPackage.addEventListener('click',()=>setMode('package'));
      // initialize
      window.addEventListener('load',()=>setMode('monthly'));
    })();
  </script>
</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>FAQ • {{BUSINESS_NAME}}</title>
  <meta name="description" content="Common questions about working together, session flow, and confidentiality." />
  <style>
    :root{--bg:#021221;--muted:#9fb0c2;--card:#071b26;--accent:#7dd3fc}
    body{margin:0;font-family: Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;background:linear-gradient(180deg,var(--bg),#04121b);color:#e9f6fb}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px}
    .logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#b992f7);display:flex;align-items:center;justify-content:center;font-weight:700}
    nav a{margin-left:16px;color:var(--muted);font-size:15px}
    main{max-width:900px;margin:28px auto;padding:0 20px}
    h1{margin:0 0 8px}
    .intro{color:var(--muted);margin-bottom:18px}
    .accordion{background:rgba(255,255,255,0.02);padding:12px;border-radius:12px;border:1px solid rgba(255,255,255,0.03)}
    .qa{border-top:1px solid rgba(255,255,255,0.02);}
    .q{display:flex;justify-content:space-between;align-items:center;padding:14px;cursor:pointer}
    .q h3{margin:0;font-size:15px}
    .a{padding:0 14px 18px;color:var(--muted);display:none}
    .q .chev{color:var(--muted)}
    .open+.a{display:block}
    .small-note{margin-top:18px;color:var(--muted);background:rgba(255,255,255,0.01);padding:12px;border-radius:8px;border:1px solid rgba(255,255,255,0.02)}
    footer{max-width:900px;margin:22px auto;color:var(--muted);font-size:13px;padding:0 20px}
    @media (max-width:700px){nav{display:none}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center">
      <div class="logo">T</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">About</a>
      <a href="specialties.html">Specialties</a>
      <a href="approach.html">How I Work</a>
      <a href="fees.html">Fees</a>
      <a href="faq.html">FAQ</a>
      <a href="book.html">Schedule</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <h1>Frequently asked questions</h1>
    <p class="intro">Below are practical answers about what a typical engagement looks like, how I structure sessions, and limits to confidentiality. If your question isn’t here, please reach out.</p>

    <div class="accordion" id="faq">
      <div class="qa">
        <div class="q" data-key="1"><h3>What happens in a first session?</h3><div class="chev">▸</div></div>
        <div class="a">We use the first visit to clarify your immediate concerns, outline goals, and discuss scheduling and fees. It’s a chance to see if the fit feels right. I aim to be practical and collaborative about next steps.</div>
      </div>

      <div class="qa">
        <div class="q" data-key="2"><h3>How long is each appointment?</h3><div class="chev">▸</div></div>
        <div class="a">Standard sessions are 50 minutes. Some clients prefer a slightly longer session occasionally; we can plan that in advance and discuss the schedule and fee.</div>
      </div>

      <div class="qa">
        <div class="q" data-key="3"><h3>Do you use telehealth?</h3><div class="chev">▸</div></div>
        <div class="a">Yes. I meet both in person and by secure video. We’ll agree on what feels safest and most useful for your work together.</div>
      </div>

      <div class="qa">
        <div class="q" data-key="4"><h3>Will you share my notes with anyone?</h3><div class="chev">▸</div></div>
        <div class="a">Clinical notes are kept confidential within legal and ethical limits. I discuss how records are kept during intake. I will only release records with your written consent or when required by law.</div>
      </div>

      <div class="qa">
        <div class="q" data-key="5"><h3>What if I’m experiencing a crisis?</h3><div class="chev">▸</div></div>
        <div class="a">I do not provide emergency crisis services. If you are at immediate risk, please call local emergency services or a crisis line. If you’re unsure where to start, contact your local health services for 24/7 support.</div>
      </div>

      <div class="qa">
        <div class="q" data-key="6"><h3>Can you help me choose between a short package and ongoing sessions?</h3><div class="chev">▸</div></div>
        <div class="a">Yes — I’ll ask about what outcome you hope to see and how much time you can commit. Some situations are well-suited to a focused few sessions; others benefit from a monthly rhythm. We can map a plan together.</div>
      </div>
    </div>

    <div class="small-note">
      <strong>Accessibility</strong>
      <div style="margin-top:6px;color:var(--muted)">If you need accommodations for remote or in-person meetings, please tell me and I will do my best to arrange them.</div>
    </div>
  </main>

  <footer>
    <div style="max-width:900px;margin:0 auto;padding:18px 20px;color:var(--muted)">
      <div>For scheduling: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
      <div style="margin-top:8px">I maintain confidentiality within professional boundaries. I do not provide emergency services; if you are in immediate danger, call emergency services or your local crisis line.</div>
    </div>
  </footer>

  <script>
    // Simple accordion behavior
    (function(){
      const qEls = document.querySelectorAll('.q');
      qEls.forEach(q=>{
        q.addEventListener('click',()=>{
          const open = document.querySelector('.q.open');
          if(open && open!==q){ open.classList.remove('open'); }
          q.classList.toggle('open');
        });
      });
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Schedule • {{BUSINESS_NAME}}</title>
  <meta name="description" content="Choose what feels right and find the approach that fits your current state." />
  <style>
    :root{--bg:#071426;--muted:#9fb0c2;--card:#082134;--accent:#a3e9ff;--warm:#ffd6a5}
    body{margin:0;font-family: Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;background:linear-gradient(180deg,var(--bg),#02121a);color:#ecfbff}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 26px}
    nav a{margin-left:14px;color:var(--muted);font-size:15px}
    main{max-width:980px;margin:22px auto;padding:0 20px}
    .hero{padding:22px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);border-radius:12px}
    .mood-grid{display:flex;gap:12px;margin-top:16px;flex-wrap:wrap}
    .mood{background:rgba(255,255,255,0.02);padding:12px 14px;border-radius:10px;cursor:pointer;border:1px solid rgba(255,255,255,0.02);min-width:140px}
    .mood.active{outline:2px solid rgba(163,233,255,0.16);transform:translateY(-4px)}
    .method{margin-top:18px;padding:16px;border-radius:10px;background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.03)}
    .method h2{margin:0 0 6px}
    .method p{color:var(--muted)}
    .method ul{color:var(--muted);margin-top:8px}
    .book-cta{display:inline-block;margin-top:12px;padding:10px 14px;border-radius:10px;background:var(--accent);color:#02121a;font-weight:600}
    .visual{height:120px;border-radius:10px;margin-top:12px;background:linear-gradient(90deg,#052026 0%,#052026 100%);position:relative;overflow:hidden}
    .visual .shape{position:absolute;border-radius:50%;opacity:0.12}
    .mood-overwhelmed .visual{background:linear-gradient(90deg,#03101a,#06202b)}
    .mood-stuck .visual{background:linear-gradient(90deg,#1a0620,#2b0634)}
    .mood-transition .visual{background:linear-gradient(90deg,#062018,#10302e)}
    .mood-prepared .visual{background:linear-gradient(90deg,#17341a,#2b4a1a)}
    .disclaimer{margin-top:16px;color:var(--muted);font-size:13px}
    footer{max-width:980px;margin:22px auto;padding:0 20px;color:var(--muted)}
    @media (max-width:700px){.mood{min-width:48%}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center">
      <div style="width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#b992f7);display:flex;align-items:center;justify-content:center;font-weight:700">T</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">About</a>
      <a href="specialties.html">Specialties</a>
      <a href="approach.html">How I Work</a>
      <a href="fees.html">Fees</a>
      <a href="faq.html">FAQ</a>
      <a href="book.html">Schedule</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <section class="hero" id="hero">
      <h1 style="margin:0 0 6px">Find the kind of session that fits where you are</h1>
      <p style="margin:0;color:var(--muted)">Choose a mood below; I’ll suggest an approach and update the button so the next step matches that offer.</p>

      <div class="mood-grid" id="moodGrid">
        <div class="mood" data-key="overwhelmed" tabindex="0">
          <strong>Overwhelmed</strong>
          <div style="font-size:13px;color:var(--muted);margin-top:6px">Urgent, scattered, too much on the plate.</div>
        </div>
        <div class="mood" data-key="stuck" tabindex="0">
          <strong>Stuck</strong>
          <div style="font-size:13px;color:var(--muted);margin-top:6px">Repeating patterns, slow progress.</div>
        </div>
        <div class="mood" data-key="transition" tabindex="0">
          <strong>In transition</strong>
          <div style="font-size:13px;color:var(--muted);margin-top:6px">A life change asking for a plan.</div>
        </div>
        <div class="mood" data-key="prepared" tabindex="0">
          <strong>Preparing</strong>
          <div style="font-size:13px;color:var(--muted);margin-top:6px">Ready to map goals and practice new skills.</div>
        </div>
      </div>

      <div class="method" id="method">
        <h2 id="methodTitle">Choose how you feel to see a suggested approach</h2>
        <p id="methodDesc" class="desc" style="color:var(--muted)">Selecting a mood will change the recommended format and the call-to-action to reflect that next step.</p>
        <ul id="methodBullets"></ul>
        <div class="visual" id="visual">
          <div class="shape" style="width:220px;height:220px;left:-40px;top:-60px;background:linear-gradient(90deg,var(--accent),#b992f7)"></div>
        </div>
        <a id="bookCta" class="book-cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <div class="disclaimer">Sessions are confidential within ethical and legal limits. Not a crisis service. If you are at immediate risk, contact emergency services or local crisis resources.</div>
      </div>
    </section>
  </main>

  <footer>
    <div style="max-width:980px;margin:0 auto;padding:18px 20px;color:var(--muted)">Questions about fit: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
  </footer>

  <script>
    // Mood-to-Method selector
    (function(){
      const map = {
        overwhelmed: {
          title: 'Stabilize & Prioritize — Single intensive',
          desc: 'A brief, concentrated session set to reduce immediate overwhelm and create a simple action plan.',
          bullets: ['One 90-minute focused session OR two 50-minute sessions','Concrete steps to reduce immediate load','Follow-up items you can use between meetings'],
          cta: 'Request an Intensive'
        },
        stuck: {
          title: 'Untangle Patterns — Short series',
          desc: 'A sequence of sessions to notice patterns and test small changes with hands-on support.',
          bullets: ['Four 50-minute sessions over 4–8 weeks','Practical experiments to shift habitual reactions','Reflections and skills to practice at home'],
          cta: 'Begin a Short Series'
        },
        transition: {
          title: 'Chart the Next Phase — Bridge package',
          desc: 'Targeted sessions for transitions: assess options, clarify values, and choose next steps.',
          bullets: ['Three to six sessions tailored to your timeline','Decision-focused conversations and planning','Tools to manage the change with less reactivity'],
          cta: 'Plan a Bridge Package'
        },
        prepared: {
          title: 'Practice & Grow — Monthly partnership',
          desc: 'Ongoing weekly or biweekly meetings to practice new skills and track steady progress.',
          bullets: ['Regular sessions for skill building','Space to test and refine long-term goals','A predictable rhythm of support'],
          cta: 'Start a Monthly Rhythm'
        }
      };

      const moodGrid = document.getElementById('moodGrid');
      const methodTitle = document.getElementById('methodTitle');
      const methodDesc = document.getElementById('methodDesc');
      const bulletsEl = document.getElementById('methodBullets');
      const bookCta = document.getElementById('bookCta');
      const hero = document.getElementById('hero');
      const visuals = document.getElementById('visual');

      function setMood(key){
        const data = map[key];
        methodTitle.textContent = data.title;
        methodDesc.textContent = data.desc;
        bulletsEl.innerHTML = '';
        data.bullets.forEach(b=>{ const li=document.createElement('li'); li.textContent=b; bulletsEl.appendChild(li); });
        bookCta.textContent = data.cta;
        // visual morph: adjust class on body or hero
        hero.classList.remove('mood-overwhelmed','mood-stuck','mood-transition','mood-prepared');
        hero.classList.add('mood-'+key);
        // subtle motion effect on visual
        visuals.querySelectorAll('.shape').forEach(s=>s.remove());
        const s1 = document.createElement('div'); s1.className='shape';
        s1.style.width='220px'; s1.style.height='220px'; s1.style.left='-40px'; s1.style.top='-60px';
        if(key==='overwhelmed'){ s1.style.background='radial-gradient(circle,#ff9b9b,#ff7a7a)'; }
        if(key==='stuck'){ s1.style.background='radial-gradient(circle,#9b9bff,#7a7aff)'; }
        if(key==='transition'){ s1.style.background='radial-gradient(circle,#9bffcf,#7affd6)'; }
        if(key==='prepared'){ s1.style.background='radial-gradient(circle,#ffd6a5,#ffb86b)'; }
        visuals.appendChild(s1);
      }

      moodGrid.addEventListener('click',function(e){
        const tgt = e.target.closest('.mood');
        if(!tgt) return;
        Array.from(moodGrid.children).forEach(n=>n.classList.remove('active'));
        tgt.classList.add('active');
        setMood(tgt.dataset.key);
      });

      // keyboard accessible
      moodGrid.addEventListener('keydown',function(e){
        if(e.key==='Enter' || e.key===' '){
          const tgt = e.target.closest('.mood');
          if(tgt){ tgt.click(); e.preventDefault(); }
        }
      });

      // initialize with a gentle default
      setMood('transition');
      Array.from(moodGrid.children).forEach(n=>{ if(n.dataset.key==='transition') n.classList.add('active'); });
    })();
